<div class="rounded-md border overflow-x-auto"><table class="w-full caption-bottom text-sm"><thead class="border-b"><tr>@foreach([''=>'','name'=>'Student','nim'=>'NIM','group'=>'Group','date'=>'Date','time'=>'Time','location'=>'Location','examiners'=>'Examiners','status'=>'Status','actions'=>'Actions'] as $key=>$label)<th class="h-10 px-2 text-left align-middle font-medium whitespace-nowrap {{ $key==='actions'?'text-right':'' }}">@if(in_array($key,['name','date','status']))<button type="button" @click="sort('{{ $key }}')" class="inline-flex items-center gap-2">{{ $label }}<x-capstone::icon name="ArrowUpDown" class="size-4 text-muted-foreground" /></button>@else{{ $label }}@endif</th>@endforeach</tr></thead>
    <template x-for="s in visible" :key="s.id"><tbody><tr class="border-b cursor-pointer hover:bg-muted/50" @click="toggle(s.id)" :class="s.status==='CANCELLED'?'text-muted-foreground/60':''">
