        <td class="p-2"><span class="font-semibold" x-text="students(s)[0]?.name || 'N/A'"></span><span x-show="students(s).length>1" class="text-xs text-muted-foreground ml-1" x-text="'+'+(students(s).length-1)+' more'"></span></td>
        <td class="p-2 text-sm font-mono tabular-nums text-muted-foreground" x-text="students(s)[0]?.nim || '-'"></td><td class="p-2 text-sm tabular-nums text-muted-foreground" x-text="s.group?.code || '#'+s.group_id"></td>
        <td class="p-2 text-sm whitespace-nowrap font-mono tabular-nums text-muted-foreground" x-text="date(s.date)"></td><td class="p-2 text-sm whitespace-nowrap font-mono tabular-nums text-muted-foreground"><span x-text="s.start_time?.slice(0,5)"></span><span class="text-muted-foreground/40 mx-0.5">–</span><span x-text="s.end_time?.slice(0,5)"></span></td><td class="p-2 text-sm text-muted-foreground" x-text="location(s)"></td><td class="p-2 text-xs text-muted-foreground"><p x-text="s.examiner1?.name || '—'"></p><p x-text="s.examiner2?.name || '—'"></p></td>
        <td class="p-2"><span class="inline-flex items-center rounded-md border px-2 py-0.5 text-xs font-medium" :class="s.status==='SCHEDULED'?'bg-blue-100 text-blue-800 border-blue-200':s.status==='DONE'?'bg-green-100 text-green-800 border-green-200':'bg-gray-100 text-gray-700 border-gray-200'" x-text="statusLabel(s.status)"></span></td>
        <td class="p-2"><div class="flex items-center justify-end gap-1" @click.stop><x-capstone::feature-link href="/admin/evaluation-summary/1" ::href="url('/admin/evaluation-summary/'+s.id)" x-show="s.status!=='CANCELLED'" class="inline-flex items-center rounded-md border px-2 h-7 text-[13px] shadow-xs hover:bg-accent"><x-capstone::icon name="FileText" class="mr-1 h-3.5 w-3.5" />Eval</x-capstone::feature-link><button type="button" x-show="s.status==='SCHEDULED'" @click="open(s)" class="rounded-md border h-7 px-3 text-[13px] shadow-xs hover:bg-accent">Edit</button><button type="button" x-show="s.status==='SCHEDULED'" @click="confirmCancel(s)" class="rounded-md h-7 px-3 text-[13px] text-destructive hover:bg-accent">Cancel</button></div></td>
    </tr><tr x-show="expanded.includes(s.id)" class="bg-muted/30 border-b"><td colspan="10" class="p-4"><div class="grid grid-cols-1 lg:grid-cols-2 gap-6"><div class="space-y-2"><h3 class="text-[11px] font-semibold uppercase tracking-wider text-muted-foreground/70">Defense Info</h3><p class="text-[12px] font-medium text-foreground/80" x-text="s.group?.title?.title || 'No title assigned'"></p><div class="space-y-1.5">@foreach(['Examiner 1'=>'s.examiner1?.name','Examiner 2'=>'s.examiner2?.name','Eval Deadline'=>'date(s.evaluation_deadline)'] as $label=>$expression)<div class="flex items-center justify-between"><span class="text-muted-foreground/70 text-[12px]">{{ $label }}</span><span class="text-[12px] font-medium text-foreground/80" x-text="{{ $expression }} || '—'"></span></div>@endforeach</div></div><div class="space-y-2"><h3 class="text-[11px] font-semibold uppercase tracking-wider text-muted-foreground/70">Student Info</h3><div class="space-y-1.5"><template x-for="(student,index) in students(s)" :key="student.id"><div class="border-b border-border/50 last:border-0 pb-1.5 last:pb-0"><div class="flex items-center justify-between"><span class="text-muted-foreground/70 text-[12px]" x-text="'Name'+(index?' #'+(index+1):'')"></span><span class="text-[12px] font-medium text-foreground/80" x-text="student.name"></span></div><div class="flex items-center justify-between"><span class="text-muted-foreground/70 text-[12px]">NIM</span><span class="text-[12px] text-muted-foreground font-mono tabular-nums" x-text="student.nim"></span></div></div></template>@foreach(['Group'=>"'#'+s.group_id",'Period'=>"s.period?.name || s.group?.period?.name",'Notes'=>'s.notes'] as $label=>$expression)<div class="flex items-center justify-between"><span class="text-muted-foreground/70 text-[12px]">{{ $label }}</span><span class="text-[12px] text-muted-foreground" x-text="{{ $expression }} || '—'"></span></div>@endforeach</div></div></div></td></tr></tbody></template>
</table></div>
<div class="mt-4 flex flex-wrap items-center justify-between gap-4 text-sm"><span class="text-muted-foreground" x-text="'Showing '+((currentPage-1)*Number(perPage)+1)+' to '+Math.min(currentPage*Number(perPage),filtered.length)+' of '+filtered.length"></span><div class="flex items-center gap-3"><label class="flex items-center gap-2">Rows per page<select x-model.number="perPage" @change="page=1" class="rounded-md border p-1"><option>10</option><option>25</option><option>50</option></select></label><span x-text="'Page '+currentPage+' of '+totalPages"></span><x-capstone::button variant="outline" size="icon-sm" aria-label="Previous page" ::disabled="currentPage<=1" @click="page=currentPage-1"><x-capstone::icon name="ChevronLeft" /></x-capstone::button><x-capstone::button variant="outline" size="icon-sm" aria-label="Next page" ::disabled="currentPage>=totalPages" @click="page=currentPage+1"><x-capstone::icon name="ChevronRight" /></x-capstone::button></div></div>
